from itertools import combinations
from random import Random

_MAX_N = 200_000
_REFERENCE_LIMIT = 16


def _bounded_integer(token: str) -> int | None:
    negative = token.startswith("-")
    digits = token[1:] if token.startswith(("+", "-")) else token
    if not digits.isascii() or not digits.isdecimal():
        return None

    digits = digits.lstrip("0")
    limit = str(_MAX_N)
    if len(digits) > len(limit) or (
        len(digits) == len(limit) and digits > limit
    ):
        magnitude = _MAX_N + 1
    else:
        magnitude = int(digits or "0")
    return -magnitude if negative else magnitude


def _read_tree(inp: str) -> tuple[list[list[int]], list[tuple[int, int]]] | None:
    tokens = inp.split()
    if not tokens:
        return None

    size = _bounded_integer(tokens[0])
    if size is None or not 1 <= size <= _MAX_N:
        return None
    if len(tokens) != 2 * size - 1:
        return None

    neighbors = [[] for _ in range(size)]
    edges = []
    for index in range(1, len(tokens), 2):
        a = _bounded_integer(tokens[index])
        b = _bounded_integer(tokens[index + 1])
        if a is None or b is None or not (1 <= a <= size and 1 <= b <= size):
            return None
        if a == b:
            return None
        a -= 1
        b -= 1
        neighbors[a].append(b)
        neighbors[b].append(a)
        edges.append((a, b))

    seen = {0}
    pending = [0]
    while pending:
        vertex = pending.pop()
        for neighbor in neighbors[vertex]:
            if neighbor not in seen:
                seen.add(neighbor)
                pending.append(neighbor)

    # Connectivity with exactly size - 1 edges also excludes parallel edges.
    if len(seen) != size:
        return None
    return neighbors, edges


def validate_input(inp: str) -> bool:
    return _read_tree(inp) is not None


def _format_tree(size: int, edges: list[tuple[int, int]]) -> str:
    return "\n".join([str(size)] + [f"{a} {b}" for a, b in edges]) + "\n"


def gen_small(seed: int, n: int) -> list[str]:
    rng = Random(seed)
    cases = [
        (1, []),
        (5, [(1, 2), (1, 3), (1, 4), (1, 5)]),
        (2, [(1, 2)]),
        (4, [(1, 2), (1, 3), (1, 4)]),
        (8, [(i, i + 1) for i in range(1, 8)]),
        (8, [(1, i) for i in range(2, 9)]),
        (8, [(1, 2), (1, 3), (1, 4), (1, 5), (2, 6), (2, 7), (2, 8)]),
        (9, [(1, 3), (2, 3), (1, 4), (1, 5), (1, 6), (2, 7), (2, 8), (2, 9)]),
    ]
    inputs = []
    for index in range(n):
        if index < len(cases):
            size, edges = cases[index]
        else:
            size = rng.randint(1, 8)
            edges = [(rng.randrange(1, child), child) for child in range(2, size + 1)]

        labels = list(range(1, size + 1))
        rng.shuffle(labels)
        relabeled = [(labels[a - 1], labels[b - 1]) for a, b in edges]
        rng.shuffle(relabeled)
        inputs.append(_format_tree(size, relabeled))
    return inputs


def gen_stress(seed: int) -> list[str]:
    rng = Random(seed)
    center = rng.randint(1, _MAX_N)
    star_edges = [(center, v) for v in range(1, _MAX_N + 1) if v != center]
    star = _format_tree(_MAX_N, star_edges)

    spine_size = (_MAX_N - 2) // 3
    deep_edges = [(v, v + 1) for v in range(1, spine_size)]
    next_leaf = spine_size + 1
    for vertex in range(1, spine_size + 1):
        leaf_count = 3 if vertex in (1, spine_size) else 2
        for _ in range(leaf_count):
            deep_edges.append((vertex, next_leaf))
            next_leaf += 1

    return [star, _format_tree(next_leaf - 1, deep_edges)]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    tree = _read_tree(inp)
    if tree is None:
        return [("POST-1", "Input does not encode a tree within the stated bounds.")]

    tokens = out.split()
    answer = _bounded_integer(tokens[0]) if len(tokens) == 1 else None
    if answer is None:
        return [("POST-2", "Expected exactly one decimal integer token.")]

    neighbors, _ = tree
    eligible = sum(len(adjacent) >= 4 for adjacent in neighbors)
    if answer == -1:
        if eligible:
            return [("POST-3", "A vertex with four neighbors gives a feasible alkane.")]
        return []
    if eligible == 0:
        return [("POST-3", "Every input vertex has degree below 4, so the answer is -1.")]
    if not 5 <= answer <= len(neighbors):
        return [("POST-4", "A feasible vertex count must lie between 5 and N.")]
    if (answer - 2) % 3 != 0:
        return [("POST-4", "A feasible vertex count must have the form 3k + 2.")]
    if (answer - 2) // 3 > eligible:
        return [("POST-4", "The count requires more degree-4 vertices than the input permits.")]
    return []


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    rng = Random(seed)
    pairs = []
    for index, original in enumerate(gen_small(seed, n)):
        neighbors, edges = _read_tree(original)
        size = len(neighbors)
        if index % 2 == 0 and edges:
            labels = list(range(1, size + 1))
            rng.shuffle(labels)
            transformed = [(labels[b], labels[a]) for a, b in reversed(edges)]
            pairs.append(("POST-4", "equal", original, _format_tree(size, transformed)))
        else:
            # Attaching at a maximum-degree vertex also exercises crossings of degree 4.
            parent = max(range(size), key=lambda vertex: len(neighbors[vertex]))
            extended = [(a + 1, b + 1) for a, b in edges]
            extended.append((parent + 1, size + 1))
            pairs.append(("POST-4", "le", original, _format_tree(size + 1, extended)))
    return pairs


def reference_small(inp: str) -> str | None:
    tree = _read_tree(inp)
    if tree is None:
        return None
    neighbors, edges = tree
    if len(neighbors) > _REFERENCE_LIMIT:
        return None

    best = -1
    for edge_count in range(1, len(edges) + 1):
        for chosen in combinations(edges, edge_count):
            degrees = {}
            for a, b in chosen:
                degrees[a] = degrees.get(a, 0) + 1
                degrees[b] = degrees.get(b, 0) + 1

            # Chosen edges form a forest. This equality tests connectivity.
            if len(degrees) != edge_count + 1:
                continue
            if 4 in degrees.values() and all(d in (1, 4) for d in degrees.values()):
                best = max(best, len(degrees))
    return f"{best}\n"
